               and grid[r + 1][c] == 3 and grid[r][c - 1] == 3
               and grid[r][c + 1] == 3]
    if hollows and centers:
        # When multiple hollow pluses occur, the one nearest a colored center
        # is the active gap; ties are resolved by row-major order.
        gap_col = min(hollows,
